def createparser():
    """Create the argument parser for the pysemver command-line interface.

    :return: The configured ArgumentParser instance
    :rtype: argparse.ArgumentParser
    """
    import argparse

    parser = argparse.ArgumentParser(
        prog='pysemver',
        description='Semantic Versioning command-line tool'
    )

    subparsers = parser.add_subparsers(dest='command', help='Available commands')

    # Compare command
    compare_parser = subparsers.add_parser('compare', help='Compare two versions')
    compare_parser.add_argument('version1', help='First version')
    compare_parser.add_argument('version2', help='Second version')

    # Bump command
    bump_parser = subparsers.add_parser('bump', help='Bump a version component')
    bump_parser.add_argument('version', help='Version to bump')
    bump_parser.add_argument('component', choices=['major', 'minor', 'patch', 'prerelease', 'build'],
                            help='Component to bump')

    # Finalize command
    finalize_parser = subparsers.add_parser('finalize', help='Remove prerelease and build metadata')
    finalize_parser.add_argument('version', help='Version to finalize')

    return parser


def process(args):
    """Process the parsed arguments and perform the requested operation.

    :param args: The parsed arguments namespace
    :type args: argparse.Namespace
    :return: The result of the operation as a string
    :rtype: str
    """
    if args.command == 'compare':
        result = compare(args.version1, args.version2)
        return str(result)
    elif args.command == 'bump':
        if args.component == 'major':
            return bump_major(args.version)
        elif args.component == 'minor':
            return bump_minor(args.version)
        elif args.component == 'patch':
            return bump_patch(args.version)
        elif args.component == 'prerelease':
            return bump_prerelease(args.version)
        elif args.component == 'build':
            return bump_build(args.version)
    elif args.command == 'finalize':
        return finalize_version(args.version)


def main(argv=None):
    """Main entry point for the pysemver command-line interface.

    :param argv: Command line arguments (defaults to sys.argv[1:])
    :type argv: list of str, optional
    :return: Exit code (0 for success, non-zero for error)
    :rtype: int
    """
    parser = createparser()
    args = parser.parse_args(argv)

    if args.command is None:
        parser.print_help()
        return 1

    try:
        result = process(args)
        print(result)
        return 0
    except ValueError as e:
        print("Error: %s" % e, file=sys.stderr)
        return 1


if __name__ == "__main__":
    import sys
    sys.exit(main())
